"""安装器（独立脚本，与 uninstaller.py 解耦）。

用法:
    python installer.py
    或双击 installer.exe

资源:
    主程序 Edge快捷方式守护.exe 与卸载器 uninstaller.exe
    以 base64 形式嵌入在本脚本的 _PAYLOAD 中，
    安装时还原写入安装目录。

行为:
    1. 选择安装目录（默认 %LOCALAPPDATA%\\Programs\\Edge快捷方式守护\\）
    2. 解 base64 还原主程序 + 卸载器，写入安装目录
    3. 生成默认 config.json
    4. 可选：创建开机启动任务（schtasks）
    5. 可选：创建个人桌面快捷方式（带 --gui 参数）
    6. 写入 HKCU\\...\\Uninstall\\EdgeShortcutGuard
"""
import base64
import os
import shutil
import subprocess
import sys
import tkinter as tk
from tkinter import ttk, messagebox, filedialog

APP_NAME = "Edge快捷方式守护"
APP_DIR_NAME = "Edge快捷方式守护"
TASK_NAME = "EdgeShortcutGuard"
REG_UNINSTALL = r"Software\Microsoft\Windows\CurrentVersion\Uninstall\EdgeShortcutGuard"
REG_APP = r"Software\EdgeShortcutGuard"
PUBLISHER = "zhangruiyang120427"
DEFAULT_DESKTOP_LNK = "Edge快捷方式守护.lnk"
MAIN_EXE_NAME = "Edge快捷方式守护.exe"
UNINSTALL_EXE_NAME = "uninstaller.exe"

# 嵌入的资源：build.py 会用 base64 填充以下两个变量。
# 如果为空表示「未注入」，运行时会报错提示。
_PAYLOAD = {
    MAIN_EXE_NAME: b"",
    UNINSTALL_EXE_NAME: b"",
}


def _payload_ok() -> tuple[bool, str]:
    if not _PAYLOAD.get(MAIN_EXE_NAME):
        return False, f"{MAIN_EXE_NAME} 未嵌入，请先运行 build.py 注入资源"
    if not _PAYLOAD.get(UNINSTALL_EXE_NAME):
        return False, f"{UNINSTALL_EXE_NAME} 未嵌入，请先运行 build.py 注入资源"
    return True, ""


# ---------- 路径 ----------
def default_install_dir() -> str:
    base = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~")
    return os.path.join(base, "Programs", APP_DIR_NAME)


def desktop_dir() -> str:
    return os.path.join(os.path.expanduser("~"), "Desktop")


# ---------- 任务计划 ----------
def create_task(install_dir: str) -> tuple[bool, str]:
    target = os.path.join(install_dir, MAIN_EXE_NAME)
    cmd = [
        "schtasks", "/create",
        "/tn", TASK_NAME,
        "/tr", f'"{target}" --silent',
        "/sc", "onlogon",
        "/rl", "limited",
        "/f",
    ]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True)
        if r.returncode != 0:
            return False, (r.stderr or r.stdout or "schtasks 调用失败").strip()
        return True, ""
    except Exception as e:
        return False, str(e)


# ---------- 桌面快捷方式 ----------
def create_desktop_shortcut(install_dir: str) -> tuple[bool, str]:
    import win32com.client
    target = os.path.join(install_dir, MAIN_EXE_NAME)
    lnk = os.path.join(desktop_dir(), DEFAULT_DESKTOP_LNK)
    try:
        shell = win32com.client.Dispatch("WScript.Shell")
        sc = shell.CreateShortCut(lnk)
        sc.TargetPath = target
        sc.Arguments = "--gui"
        sc.WorkingDirectory = install_dir
        sc.IconLocation = f"{target},0"
        sc.WindowStyle = 1
        sc.Description = f"{APP_NAME}（带 GUI 启动）"
        sc.Save()
        return True, lnk
    except Exception as e:
        return False, str(e)


# ---------- 注册表 ----------
def _reg_add(key: str, name: str, value: str, regtype: str = "REG_SZ") -> None:
    subprocess.run(
        ["reg", "add", key, "/v", name, "/t", regtype, "/d", value, "/f"],
        capture_output=True,
    )


def write_registry(install_dir: str) -> tuple[bool, str]:
    uninstaller = os.path.join(install_dir, UNINSTALL_EXE_NAME)
    icon = os.path.join(install_dir, MAIN_EXE_NAME)
    try:
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "DisplayName", APP_NAME)
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "InstallLocation", install_dir)
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "UninstallString", f'"{uninstaller}"')
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "DisplayIcon", f"{icon},0")
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "Publisher", PUBLISHER)
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "DisplayVersion", "2.0.0")
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "NoModify", "1", "REG_DWORD")
        _reg_add(r"HKCU\\" + REG_UNINSTALL, "NoRepair", "1", "REG_DWORD")
        _reg_add(r"HKCU\\" + REG_APP, "InstallLocation", install_dir)
        return True, ""
    except Exception as e:
        return False, str(e)


# ---------- 文件写出 ----------
def write_default_config(target: str) -> None:
    import json
    cfg = {
        "edge_std_path": r"C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
        "desktop_paths": [
            os.path.expanduser("~/Desktop"),
            r"C:\\Users\\Public\\Desktop",
        ],
        "desktop_aliases": ["个人桌面", "公共桌面"],
        "lnk_name": "Microsoft Edge.lnk",
        "toast_duration_seconds": 25,
        "silent_sleep_after_toast": 2,
        "ota_enabled": True,
        "ota_repo": "zhangruiyang120427/edge-shortcut-guard",
        "edge_std_paths": None,
        "lnk_names": None,
    }
    with open(target, "w", encoding="utf-8") as f:
        json.dump(cfg, f, indent=2, ensure_ascii=False)


def write_payload(install_dir: str) -> tuple[bool, str]:
    try:
        os.makedirs(install_dir, exist_ok=True)
        for name, data in _PAYLOAD.items():
            if not data:
                return False, f"资源 {name} 未注入"
            with open(os.path.join(install_dir, name), "wb") as f:
                f.write(base64.b64decode(data))
        write_default_config(os.path.join(install_dir, "config.json"))
        return True, ""
    except Exception as e:
        return False, str(e)


# ---------- 安装流程 ----------
def do_install(install_dir: str, do_startup: bool, do_desktop: bool, log) -> int:
    ok, err = _payload_ok()
    if not ok:
        log(err, error=True)
        return 1

    log("开始安装")
    log(f"安装目录: {install_dir}")
    log(f"开机启动: {do_startup}")
    log(f"桌面快捷方式: {do_desktop}")

    ok, err = write_payload(install_dir)
    if not ok:
        log(f"写入文件失败: {err}", error=True)
        return 1
    log("已写入主程序、卸载器、配置文件")

    if do_startup:
        ok, err = create_task(install_dir)
        log("已创建开机启动任务" if ok else f"创建任务计划失败: {err}", error=not ok)

    if do_desktop:
        ok, err = create_desktop_shortcut(install_dir)
        log(f"已创建桌面快捷方式: {err}" if ok else f"创建桌面快捷方式失败: {err}", error=not ok)

    ok, err = write_registry(install_dir)
    log("已写入卸载注册表" if ok else f"写注册表失败: {err}", error=not ok)

    log("安装完成")
    return 0


# ---------- 安装 UI ----------
class InstallWindow(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title(f"{APP_NAME} - 安装")
        self.geometry("560x380")
        self.resizable(False, False)

        body = ttk.Frame(self, padding=14)
        body.pack(fill=tk.BOTH, expand=True)

        ttk.Label(body, text=f"安装 {APP_NAME}", font=("Segoe UI", 12, "bold")).pack(anchor=tk.W)

        dir_frame = ttk.Frame(body)
        dir_frame.pack(fill=tk.X, pady=(12, 4))
        ttk.Label(dir_frame, text="安装目录:").pack(anchor=tk.W)
        row = ttk.Frame(dir_frame)
        row.pack(fill=tk.X, pady=4)
        self.dir_var = tk.StringVar(value=default_install_dir())
        ttk.Entry(row, textvariable=self.dir_var, width=60).pack(side=tk.LEFT, fill=tk.X, expand=True)
        ttk.Button(row, text="浏览…", command=self._pick_dir).pack(side=tk.LEFT, padx=(6, 0))

        opt_frame = ttk.LabelFrame(body, text="选项", padding=8)
        opt_frame.pack(fill=tk.X, pady=8)
        self.var_startup = tk.BooleanVar(value=True)
        self.var_desktop = tk.BooleanVar(value=True)
        ttk.Checkbutton(
            opt_frame, text="开机启动检查（创建任务计划程序）",
            variable=self.var_startup,
        ).pack(anchor=tk.W, pady=2)
        ttk.Checkbutton(
            opt_frame, text="创建桌面快捷方式（个人桌面，使用 --gui 参数）",
            variable=self.var_desktop,
        ).pack(anchor=tk.W, pady=2)

        self.log_text = tk.Text(body, height=7, font=("Consolas", 9), state=tk.DISABLED)
        self.log_text.pack(fill=tk.BOTH, expand=True, pady=(8, 0))

        btns = ttk.Frame(self, padding=(14, 0, 14, 14))
        btns.pack(fill=tk.X)
        ttk.Button(btns, text="取消", command=self.destroy).pack(side=tk.RIGHT)
        ttk.Button(btns, text="安装", command=self._on_install).pack(side=tk.RIGHT, padx=(0, 6))

    def _pick_dir(self):
        d = filedialog.askdirectory(title="选择安装目录", initialdir=self.dir_var.get())
        if d:
            self.dir_var.set(d)

    def _log(self, msg: str, error: bool = False):
        self.log_text.config(state=tk.NORMAL)
        self.log_text.insert(tk.END, msg + "\n", "err" if error else "info")
        self.log_text.tag_config("err", foreground="#b00020")
        self.log_text.tag_config("info", foreground="black")
        self.log_text.see(tk.END)
        self.log_text.config(state=tk.DISABLED)
        self.update_idletasks()

    def _on_install(self):
        d = self.dir_var.get().strip()
        if not d:
            messagebox.showwarning("提示", "请选择安装目录")
            return
        if os.path.exists(d) and os.listdir(d):
            if not messagebox.askyesno("确认", f"目录已存在且不为空:\n{d}\n继续安装?"):
                return
        msg = f"即将安装到:\n{d}\n\n"
        if self.var_startup.get():
            msg += "• 创建开机启动任务（登录时静默检查）\n"
        if self.var_desktop.get():
            msg += "• 创建桌面快捷方式（个人桌面）\n"
        msg += "\n确定吗？"
        if not messagebox.askyesno("确认", msg):
            return

        self._log("...")
        do_install(d, self.var_startup.get(), self.var_desktop.get(), self._log)
        messagebox.showinfo("完成", "安装完成")
        self.destroy()


def main():
    InstallWindow().mainloop()


if __name__ == "__main__":
    main()